1	import { Suspense } from "react";
2	import { getOptionalUser } from "./_lib/server-auth";
3	import HomeClient from "./page-client";
4	
5	/**
6	 * Server Component entry point for "/". Fetches the user server-side
7	 * so the first HTML response already shows the correct view (landing
8	 * for anon visitors, dashboard for logged-in users) with no flash.
9	 *
10	 * Only THIS page pays the Supabase getUser() cost — every other public
11	 * page (/changelog, /book-demo, /auth, /robots.txt, /sitemap.xml)
12	 * stays fully static because the root layout is synchronous.
13	 */
14	export default async function HomePage() {
15	  const user = await getOptionalUser();
16	  return (
17	    <Suspense fallback={null}>
18	      <HomeClient initialIsAuthed={!!user} />
19	    </Suspense>
20	  );
21	}
