1	import { NextResponse, type NextRequest } from "next/server";
2	import { updateSession } from "@/integrations/supabase/middleware";
3	
4	// Next.js 16 renamed the `middleware` convention to `proxy`. The exported
5	// function name should now be `proxy` (though `middleware` still works
6	// with a deprecation warning). See:
7	// https://nextjs.org/docs/messages/middleware-to-proxy
8	
9	// Routes that require an authenticated user. Unauthenticated visitors
10	// are redirected to /auth.
11	const PROTECTED_PREFIXES = [
12	  "/jobs",
13	  "/profile",
14	  "/billing",
15	  "/settings",
16	  "/team",
17	  "/tasks",
18	  "/activity",
19	  "/career-settings",
20	  "/integrations",
21	  "/reports",
22	  "/agency",
23	  "/talent-pool",
24	  "/sequences",
25	] as const;
26	
27	// Admin-only routes. Non-admin visitors are redirected to /.
28	// Admin role verification happens in the page's own layout via
29	// requireAdmin() since middleware can't query user_roles without a
30	// round-trip that would slow every request.
31	const ADMIN_PREFIXES = ["/admin"] as const;
32	
33	function isProtectedPath(pathname: string): boolean {
34	  return PROTECTED_PREFIXES.some(
35	    (prefix) => pathname === prefix || pathname.startsWith(`${prefix}/`),
36	  );
37	}
38	
39	function isAdminPath(pathname: string): boolean {
40	  return ADMIN_PREFIXES.some(
41	    (prefix) => pathname === prefix || pathname.startsWith(`${prefix}/`),
42	  );
43	}
44	
45	export async function proxy(request: NextRequest) {
46	  const { supabaseResponse, user } = await updateSession(request);
47	
48	  const { pathname } = request.nextUrl;
49	
50	  // Block unauthenticated access to protected + admin routes
51	  if ((isProtectedPath(pathname) || isAdminPath(pathname)) && !user) {
52	    const redirectUrl = request.nextUrl.clone();
53	    redirectUrl.pathname = "/auth";
54	    redirectUrl.searchParams.set("next", pathname);
55	    const redirectResponse = NextResponse.redirect(redirectUrl);
56	    // Forward any refreshed auth cookies from updateSession onto the
57	    // redirect response so a just-expired session doesn't force a
58	    // full re-login on the next request.
59	    supabaseResponse.cookies.getAll().forEach((cookie) => {
60	      redirectResponse.cookies.set(cookie);
61	    });
62	    return redirectResponse;
63	  }
64	
65	  return supabaseResponse;
66	}
67	
68	export const config = {
69	  matcher: [
70	    /*
71	     * Match all request paths except:
72	     * - _next/static (static assets)
73	     * - _next/image (image optimization)
74	     * - favicon.ico
75	     * - images, fonts, and other public static files
76	     */
77	    "/((?!_next/static|_next/image|favicon.ico|.*\\.(?:svg|png|jpg|jpeg|gif|webp|ico|woff|woff2|ttf|otf)$).*)",
78	  ],
79	};
