1	import { createServerClient } from "@supabase/ssr";
2	import { NextResponse, type NextRequest } from "next/server";
3	import type { Database } from "./types";
4	
5	export async function updateSession(request: NextRequest) {
6	  const supabaseResponse = { current: NextResponse.next({ request }) };
7	
8	  // Env vars are read lazily inside the function so `next build` can
9	  // evaluate this module during page-data collection without throwing
10	  // when NEXT_PUBLIC_SUPABASE_* aren't set (e.g. missing build ARG in
11	  // the Docker stage). The proxy runtime will still fail loudly if the
12	  // vars are missing at request time.
13	  const SUPABASE_URL = process.env.NEXT_PUBLIC_SUPABASE_URL;
14	  const SUPABASE_ANON_KEY = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;
15	
16	  if (!SUPABASE_URL || !SUPABASE_ANON_KEY) {
17	    // No auth-aware routing possible without Supabase config. Pass
18	    // the request through as anonymous so at least the public pages
19	    // render while the missing env vars are being fixed.
20	    return { supabaseResponse: supabaseResponse.current, user: null };
21	  }
22	
23	  // Fast path: if the request carries no Supabase auth cookies at all,
24	  // there's no session to refresh. Skip the getUser() network call
25	  // entirely and return a null user. This saves ~100-200ms on every
26	  // anonymous request hitting public routes (/, /auth, /changelog,
27	  // /sitemap.xml, etc.).
28	  //
29	  // Assumption: @supabase/ssr writes all auth cookies with the "sb-"
30	  // prefix (verified in @supabase/ssr dist source: chunked tokens are
31	  // "sb-<ref>-auth-token.0", PKCE verifiers are
32	  // "sb-<ref>-auth-token-code-verifier"). If this prefix ever changes
33	  // in a future @supabase/ssr release, this fast path will silently
34	  // skip session refresh for authenticated users — keep an eye on the
35	  // Supabase changelog and update the prefix check accordingly.
36	  const hasAuthCookie = request.cookies
37	    .getAll()
38	    .some((c) => c.name.startsWith("sb-"));
39	  if (!hasAuthCookie) {
40	    return { supabaseResponse: supabaseResponse.current, user: null };
41	  }
42	
43	  const supabase = createServerClient<Database>(
44	    SUPABASE_URL,
45	    SUPABASE_ANON_KEY,
46	    {
47	      cookies: {
48	        getAll() {
49	          return request.cookies.getAll();
50	        },
51	        setAll(cookiesToSet) {
52	          cookiesToSet.forEach(({ name, value }) =>
53	            request.cookies.set(name, value),
54	          );
55	          supabaseResponse.current = NextResponse.next({ request });
56	          cookiesToSet.forEach(({ name, value, options }) =>
57	            supabaseResponse.current.cookies.set(name, value, options),
58	          );
59	        },
60	      },
61	    },
62	  );
63	
64	  // CRITICAL: call getUser() (not getSession()) — this refreshes the auth
65	  // token. Skipping or using getSession() will break auth cookies.
66	  const {
67	    data: { user },
68	  } = await supabase.auth.getUser();
69	
70	  return { supabaseResponse: supabaseResponse.current, user };
71	}
