3	import { Suspense, lazy } from "react";
4	import { useAuth } from "@/hooks/useAuth";
5	
6	const Index = lazy(() => import("@/legacy-pages/Index"));
7	const LandingPage = lazy(() => import("@/components/LandingPage"));
8	
9	const PageLoader = () => (
10	  <div className="flex h-svh w-full items-center justify-center bg-background">
11	    <div className="h-8 w-8 animate-pulse rounded-full bg-muted" />
12	  </div>
13	);
