15	/**
16	 * Client shell for "/". Receives `initialIsAuthed` from the server so
17	 * the first paint already renders the correct component (no flash).
18	 * After hydration, reconciles with the live client auth state in case
19	 * the user logged out in another tab or the server cookie was stale.
20	 */
21	export default function HomeClient({
22	  initialIsAuthed,
23	}: {
24	  initialIsAuthed: boolean;
25	}) {
26	  const { user, loading } = useAuth();
27	
28	  // Before the client auth context has hydrated, trust the server signal.
29	  // After hydration, use the live user value.
30	  const isAuthed = loading ? initialIsAuthed : !!user;
31	
32	  return (
33	    <Suspense fallback={<PageLoader />}>
34	      {isAuthed ? <Index /> : <LandingPage />}
35	    </Suspense>
36	  );
37	}
