22	export interface PastJob {
23	  id: string;
24	  title: string | null;
25	  job_description: string;
26	  status: string;
27	  created_at: string;
28	  resume_count: number;
29	  jd_analysis_json: any;
30	  dynamic_weights_json: Record<string, number> | null;
