4	/**
5	 * Server-side guard for protected pages. Call at the top of a Server
6	 * Component page.tsx or layout.tsx. Redirects to /auth if no session.
7	 *
8	 * This is a second line of defense — the Next.js proxy (root proxy.ts)
9	 * is the first gate and should redirect before the RSC even runs. This
10	 * helper also returns the user so pages can use it directly.
11	 */
12	export async function requireUser() {
13	  const supabase = await createClient();
14	  const {
15	    data: { user },
16	  } = await supabase.auth.getUser();
17	
18	  if (!user) {
19	    redirect("/auth");
20	  }
21	  return user;
22	}
